  1→import { notFound } from "next/navigation";
  2→import { PROJECTS, getProject, CASE_STUDIES } from "@/lib/projects";
  3→import { MetaTag } from "@/components/MetaTag";
  4→import { PlaceholderImage } from "@/components/PlaceholderImage";
  5→import { CaseStudySection } from "@/components/CaseStudySection";
  6→import Link from "next/link";
  7→import type { Metadata } from "next";
  8→
  9→interface PageProps {
 10→  params: Promise<{ slug: string }>;
 11→}
 12→
 13→export async function generateStaticParams() {
 14→  return PROJECTS.map((p) => ({ slug: p.slug }));
 15→}
 16→
 17→export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
 18→  const { slug } = await params;
 19→  const project = getProject(slug);
 20→  if (!project) return {};
 21→  return {
 22→    title: project.title,
 23→    description: project.desc,
 24→  };
 25→}
 26→
 27→export default async function ProjectPage({ params }: PageProps) {
 28→  const { slug } = await params;
 29→  const project = getProject(slug);
 30→  if (!project) notFound();
 31→
 32→  const caseStudy = CASE_STUDIES[project.slug];
 33→  const idx = PROJECTS.findIndex((p) => p.slug === project.slug);
 34→  const prev = idx > 0 ? PROJECTS[idx - 1] : null;
 35→  const next = idx < PROJECTS.length - 1 ? PROJECTS[idx + 1] : null;
 36→
 37→  return (
 38→    <div style={{ paddingTop: "var(--nav-h)" }}>
 39→      {/* Header */}
 40→      <div style={{ padding: "clamp(40px, 8vh, 100px) var(--pad) clamp(32px, 4vh, 60px)", maxWidth: "var(--max-w)", margin: "0 auto" }}>
 41→        <div style={{ display: "flex", gap: "clamp(32px, 4vw, 80px)", alignItems: "flex-start", flexWrap: "wrap" }}>
 42→          <div style={{ flex: "1 1 400px" }}>
 43→            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 16 }}>
 44→              <MetaTag label={project.category} />
 45→              <MetaTag label={project.year} />
 46→            </div>
 47→            <h1 style={{ fontSize: "clamp(32px, 4vw, 56px)", fontWeight: 400, letterSpacing: "-0.02em", color: "var(--text)", margin: "0 0 16px", lineHeight: 1.1 }}>
 48→              {project.title}
 49→            </h1>
 50→            <p style={{ fontSize: "clamp(16px, 1.4vw, 20px)", fontWeight: 400, color: "var(--muted)", lineHeight: 1.5, margin: 0, maxWidth: 480 }}>
 51→              {project.desc}
 52→            </p>
 53→          </div>
 54→          <div style={{ flex: "0 0 200px", paddingTop: 40 }}>
 55→            {[
 56→              { label: "Role", value: "Brand Design Director" },
 57→              { label: "Year", value: project.year },
 58→              { label: "Scope", value: "Identity, Systems, Guidelines" },
 59→            ].map((item) => (
 60→              <div key={item.label} style={{ marginBottom: 20 }}>
 61→                <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 400, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 4 }}>
 62→                  {item.label}
 63→                </div>
 64→                <div style={{ fontSize: 15, color: "var(--text)", fontWeight: 400, lineHeight: 1.4 }}>
 65→                  {item.value}
 66→                </div>
 67→              </div>
 68→            ))}
 69→          </div>
 70→        </div>
 71→      </div>
 72→
 73→      {/* Hero image */}
 74→      <PlaceholderImage color={project.color} title={project.title} height="clamp(300px, 50vh, 600px)" style={{ borderRadius: 0 }} />
 75→
 76→      {/* Case study or gallery fallback */}
 77→      <div style={{ maxWidth: "var(--max-w)", margin: "0 auto", padding: "0 var(--pad)" }}>
 78→        {caseStudy ? (
 79→          caseStudy.sections.map((section, si) => (
 80→            <CaseStudySection key={si} section={section} color={project.color} title={project.title} index={si} />
 81→          ))
 82→        ) : (
 83→          <>
 84→            <div className="grid-pair" style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 20, margin: "40px 0", alignItems: "start" }}>
 85→              <PlaceholderImage color={project.color} title={`${project.title} 1`} height={440} />
 86→              <PlaceholderImage color={project.color} title={`${project.title} 2`} height={320} />
 87→            </div>
 88→            <div className="grid-pair" style={{ display: "grid", gridTemplateColumns: "1fr 2fr", gap: 20, alignItems: "start" }}>
 89→              <PlaceholderImage color={project.color} title={`${project.title} 3`} height={300} />
 90→              <PlaceholderImage color={project.color} title={`${project.title} 4`} height={460} />
 91→            </div>
 92→          </>
 93→        )}
 94→      </div>
 95→
 96→      {/* Prev/Next navigation */}
 97→      <div style={{ maxWidth: "var(--max-w)", margin: "60px auto 0", padding: "0 var(--pad)", display: "flex", justifyContent: "space-between", borderTop: "1px solid var(--border)", paddingTop: 32 }}>
 98→        {prev ? (
 99→          <Link href={`/work/${prev.slug}`} style={{ fontSize: 16, color: "var(--text)" }}>
100→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Previous</span>
101→            {prev.title}
102→          </Link>
103→        ) : <div />}
104→        {next ? (
105→          <Link href={`/work/${next.slug}`} style={{ fontSize: 16, color: "var(--text)", textAlign: "right" }}>
106→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Next</span>
107→            {next.title}
108→          </Link>
109→        ) : <div />}
110→      </div>
111→
112→      <div style={{ height: 60 }} />
113→    </div>
114→  );
115→}
